import os
import logging
import time
from collections import namedtuple

from taf.gnb.oam.commissioning.vm_wait import VMWait, TimeoutException
from taf.gnb.oam.megazone_client import megazone_client
from taf.transport.ssh import ssh
from taf.config.scf import scf
from ._robot_helper import wait_until_keyword_succeeds
from .nmap import nmap_check, is_ip_v6
from .ssh_checker import SSHChecker


class Commissioning(object):
    OAMCredentials = namedtuple('OAMCredentials', ['user', 'password'])

    TIMEOUT_CREATE_SESSION = 300
    TIMEOUT_VM_AVAILABILITY = 1220
    TIMEOUT_OAM_NODE_PORT = 7 * 60
    TIMEOUT_SITE_OAM = 400
    DEFAULT_REBOOT_TIME = 60
    OAM_CONNECTION = "OAM"
    OAM_PORT = 443
    DEFAULT_EXPECTED_STARTUP_PHASE = 2
    DEFAULT_OAM_CREDENTIALS = OAMCredentials(user='Nemuadmin',
                                             password='nemuuser')

    def __init__(self):
        self.csn = ssh()
        self.mz_client = megazone_client()
        self.scf = scf()
        self.vm_wait = VMWait()
        self._log_path = '/opt/nokia/SS_MzOam/cloud-siteoam/siteoam/logs/startup_SITEOAM.log'

    def commission(self, oam_ip, scf_xml,
                   timeout_create_session=TIMEOUT_CREATE_SESSION,
                   timeout_vm_availability=TIMEOUT_VM_AVAILABILITY,
                   expected_phase=DEFAULT_EXPECTED_STARTUP_PHASE,
                   oam_credentials=DEFAULT_OAM_CREDENTIALS,
                   oam_reboot_time=DEFAULT_REBOOT_TIME):
        logging.info("Creating REST session")
        interval_create_session = 10
        wait_until_keyword_succeeds(
            timeout_create_session, interval_create_session,
            lambda: self._create_session(oam_ip, oam_credentials))

        logging.info("Performing commissioning")
        self.mz_client.perform_commissioning(scf_path=scf_xml)
        time.sleep(oam_reboot_time)

        logging.info("waiting for oam startup (expected phase = {})".format(expected_phase))
        phase_request_interval = 2
        self._wait_for_startup_phase(oam_ip,
                                     expected_phase,
                                     phase_request_interval,
                                     timeout_vm_availability,
                                     oam_credentials)

        logging.info("Resetting cache")
        self.csn.reset_cache()

        logging.info("Logging out...")
        self.mz_client.teardown_session()

    def _create_session(self, oam_ip, oam_credentials):
        oam_url = "https://[{}]".format(oam_ip) if is_ip_v6(oam_ip) else "https://{}".format(oam_ip)
        self.mz_client.create_session(oam_url,
                                      user=oam_credentials.user,
                                      password=oam_credentials.password)

    def _wait_for_startup_phase(self, oam_ip, expected_phase, interval, timeout, credentials):
        end = time.time() + timeout
        ok = False
        current_phase = None
        while time.time() < end and not ok:
            try:
                self._create_session(oam_ip, credentials)
                startup_phase = self.mz_client.get_startup_phase()
            except Exception as e:
                msg = "Exception while waiting for startup phase: {}"
                logging.debug(msg.format(str(e)))
                time.sleep(interval)
            else:
                max_phase = int(startup_phase['maxPhases'])
                current_phase = int(startup_phase['currentPhase'])
                self._validate_expected_phase(expected_phase, max_phase)
                ok = current_phase >= expected_phase
            finally:
                self.mz_client.teardown_session()
        else:
            if not ok:
                msg = "Startup timed out. Expected phase {}, reached phase {}"
                raise TimeoutException(msg.format(expected_phase, current_phase))

    def _validate_expected_phase(self, expected_phase, max_phase):
        if max_phase < expected_phase:
            msg = "expected_phase {} has higher value than max_phases {}"
            raise ValueError(msg.format(expected_phase, max_phase))

    def get_scf_from_oam_vm(self, scf_remote_dir, scf_filename, log_path, oam_connection=OAM_CONNECTION):
        """You must create connection to OAM VM before starting this keyword! Returns path of downloaded scf."""

        scf_remote_path = os.path.join(scf_remote_dir, scf_filename)
        scf_local_path = os.path.join(log_path, scf_filename)
        logging.info("Downloading scf file from OAM")
        self.csn.download_file(scf_remote_path, scf_local_path, connection=oam_connection)
        return scf_local_path

    def modify_scf(self, input_scf, output_scf, parameters_lists):
        self.scf.load_scf(input_scf)
        exceptions = []
        for params in parameters_lists:
            try:
                self.scf.modify_scf_element(**params)
            except Exception as e:
                msg = "Exception while modyfing SCF: {}"
                logging.warning(msg.format(str(e)))
                exceptions.append(e)
        self.scf.save_scf(output_scf)
        if exceptions:
            raise Exception(exceptions)

    def wait_for_oam_node_port(self, oam_node_ip, timeout=TIMEOUT_OAM_NODE_PORT, interval=5, port=OAM_PORT):
        """Check of OAM port (443 by default)"""
        is_open = wait_until_keyword_succeeds(
            timeout, interval, lambda: nmap_check(oam_node_ip, port)) or None
        if is_open:
            logging.info("Port {} is open".format(port))

    def wait_for_siteOAM(self, alias, timeout=TIMEOUT_SITE_OAM, interval=2):
        wait_until_keyword_succeeds(timeout, interval, lambda: SSHChecker.file_exists(self.csn, alias, self._log_path))
        wait_until_keyword_succeeds(timeout, interval, lambda: SSHChecker.line_check(self.csn, alias, self._log_path))
